package de.igslandstuhl.database.attendance;import java.time.*;import java.util.*;
final class LessonSchedule{private final List<LocalTime> times;LessonSchedule(String c){try{times=Arrays.stream(c.split(",")).map(String::trim).map(LocalTime::parse).toList();if(times.size()!=6)throw new IllegalArgumentException();}catch(RuntimeException e){throw new IllegalArgumentException("Es müssen sechs gültige Stunden-Prüfzeiten konfiguriert sein.");}}Instant cutoff(LocalDate d,int l,ZoneId z,Instant n){if(l==0)return n;if(l<1||l>6)throw new IllegalArgumentException("Ungültige Unterrichtsstunde");return d.atTime(times.get(l-1)).atZone(z).toInstant();}List<String> values(){return times.stream().map(LocalTime::toString).toList();}}
